/* Válka popela — JAZYKY (etapa 12b, PLAN IV-S).
 *
 * Hra vznikla natvrdo česky. Tenhle soubor je kostra, na kterou se texty
 * postupně převádějí: slovník klíč → věta pro každý jazyk, `t(klic, param)`
 * a jazyk uložený na ÚČTU (ne v localStorage — hráč se přihlásí z jiného
 * zařízení a hra musí zůstat v jeho jazyce).
 *
 * ⚠ CO SE PŘEKLÁDÁ A CO NE
 * Jména rodů, hrdinů, krajů, předmětů a světa jsou vlastní IP Vellaru
 * a NEPŘEKLÁDAJÍ SE — Vellar zůstane Vellar, Popelná spálenina zůstane
 * Popelná spálenina, i když hraješ anglicky. Překládá se to, co něco
 * VYSVĚTLUJE: rozhraní, nápověda, popisy dovedností, hlášky, kronika.
 * Proto v tomhle souboru žádné jméno z HERO_DEFS ani FACTION_DEFS nenajdeš.
 *
 * ⚠ SERVER POSÍLÁ KLÍČE, NE VĚTY
 * Kronika i bojové reporty se skládaly na serveru jako hotová česká souvětí.
 * Od etapy 12b umí `addLog` nést `{klic, param}` a větu složí až klient —
 * jinak by hráč s anglickým klientem dostával od českého serveru české hlášky.
 * Staré volání s hotovou větou funguje dál, takže se převádí po jednom.
 *
 * Chybějící klíč se NESCHOVÁVÁ: spadne na češtinu a když ani ta není, ukáže
 * se ⟨klic⟩. Tiše zobrazený prázdný řetězec by se hledal měsíce.
 */

// `locale` je pro `toLocaleString` — oddělovač tisíců a desetinná čárka se
// mezi jazyky liší (1 234,5 × 1,234.5) a číslo bez toho vypadá jako z jiné hry.
const JAZYKY_SEZNAM = [
  { kod: "cs", jmeno: "Čeština", vlajka: "🇨🇿", locale: "cs-CZ" },
  { kod: "en", jmeno: "English", vlajka: "🇬🇧", locale: "en-GB" },
  { kod: "es", jmeno: "Español", vlajka: "🇪🇸", locale: "es-ES" },
];
// locale právě nastaveného jazyka (pro toLocaleString v rozhraní)
function cisloJazyk() {
  const j = JAZYKY_SEZNAM.find(x => x.kod === jazyk);
  return (j && j.locale) || "cs-CZ";
}
