    "pan.mimo.dohled": "? (pole není na dohled)",
    "pan.posledni.stav": "Poslední známý stav — přesnou sílu obrany odhalí jen dohled.",
    "pan.stoh.tip": "Každou armádu musíš porazit zvlášť — pole padne až s poslední. Jejich sílu odsud nepoznáš.",
