    "pan.stoh.neznas": "sílu odsud nepoznáš",
    "pan.zasoba.tip": "Jednotky v zásobě brání hlavní město a nesou ztráty z boje",
    "pan.zasoba": "(vč. {pocet} jednotek v zásobě)",
    "pan.velitel.tip": "Neutrální posádku vede velitel — jeho úroveň roste se silou pole. Nemá výbavu ani hvězdy.",
    "pan.velitel": "Velitel",
    "pan.most.tip": "Řeka je široká tři pole a přejít ji jde jen mostem. Oba břehy jsou samostatná pole spojená přes vodu — musíš dobýt ten svůj a z něj protější.",
    "pan.most": "<b>Přechod přes řeku</b> — protější břeh {breh}",
    "pan.most.drzis": "držíš",
    "pan.dve.armady.most": "brání dvě armády (velitelé úr. {uroven})",
    "pan.uzavren": "uzavřen ještě {doba}",
    "pan.uzel.tip": "Uzel brání dvě armády po polovině posádky — obě je nutné porazit na jeden zátah. Odražený zátah (i pád velitele) obě armády plně obnoví a uzel se na čas uzavře.",
    "pan.uzel": "Dvě armády uzlu — na jeden zátah",
    "pan.odolnost.tip": "Pobití posádky velkou stavbu nezabírá — otevře obléhací okno. V něm náběhy boří odolnost bez vlastních ztrát; promeškané okno stavbu obnoví i s posádkou.",
    "pan.odolnost": "Odolnost {ted}/{max}",
    "pan.okno": "obléhací okno {doba}",
    "pan.posadka.pobita": "posádka pobita",
    "pan.kraj.drzi": "Kraj drží {rod} — bez vyhlášené války boříš jen za {pct} % síly.",
    "pan.keep.tip": "Keep je jediná stavba svého kraje. Jeho posádka je násobek velké pevnosti, takže se nedá vzít jedním zátahem — bere se opakovanými nájezdy, dokud běží okno zranění.",
    "pan.keep": "<b>Keep kraje {kraj}</b> — kdo ho drží, drží kraj",
    "pan.keep.nikdo": "(zatím nikdo)",
    "pan.keep.tvuj": "držíš ho",
    "pan.keep.drzi": "drží {rod}",
    "pan.keep.obrana": "<b>Jedna armáda {muzu} mužů</b> pod jedním velitelem — nejsilnější hrdina uveze {strop}, tedy zhruba <b>{nasobek}× méně, než je potřeba</b>. Postup se ale v okně zranění SČÍTÁ: rozebírá se po nájezdech a ve víc lidech.",
    "pan.zran.tip": "Od prvního útoku se posádka nehojí a postup se sčítá napříč všemi útočníky. Až okno vyprší, pole se vrátí do plné síly.",
    "pan.zran": "<b>Okno zranění {doba}</b> · posádka rozebrána z <b>{pct} %</b> · nehojí se",
    "pan.trun.primeri": "Trůnní město chrání příměří — otevře se za {doba}.",
    "pan.keep.obrana.tip": "Keep brání JEDNA armáda, ne vlny — ale je tak velká, že ji nikdo neuveze najednou. Okno zranění (60 minut) drží posádku otevřenou a postup se SČÍTÁ napříč útočníky, takže se keep rozebírá po kusech a ve víc lidech.",
    "pan.kapital": "Srdce tvé říše. Zásoba jednotek brání město a jednotlivé agendy otevřeš v liště vpravo:",
    "pan.zakladna": "Domovská základna hrdiny — jedná v dosahu {reach} polí odtud.",
    "pan.usadit.tip": "Hrdina bude jednat v dosahu {reach} polí od této výspy (místo od kapitálu). Návrat domů základnu vrací pod kapitál.",
    "pan.usadit": "Usadit se na výspě",
    "pan.vyspa.tip.hrdina": "Obranná stavba: posádka až {cap} jednotek drží trvalou stráž nad polem i sousedy. Hrdina ji hlídá a může se v ní usadit.",
    "pan.vyspa.postavit": "Postavit výspu",
    "pan.vyspa.tip": "Obranná stavba: posádka až {cap} jednotek drží trvalou stráž nad polem i sousedy",
    "pan.posily.cesta": "Posily na cestě ({eta} s) — hrdina do jejich doručení nesmí opustit pole. Stráž držet může.",
    "pan.rozkaz.utok": "Čekající rozkaz: po doručení posil zaútočí na {pole}.",
