    "pan.uzel.tip": "Un nodo lo defienden dos ejércitos de media guarnición cada uno — hay que vencer a ambos en una sola embestida. Una embestida rechazada (o un comandante caído) restaura ambos ejércitos y cierra el nodo un tiempo.",
    "pan.uzel": "Dos ejércitos del nodo — en una sola embestida",
    "pan.odolnost.tip": "Aniquilar la guarnición no conquista una gran estructura — abre una ventana de asedio. Las embestidas dentro de ella rompen la resistencia sin bajas propias; si la ventana se pierde, la estructura y su guarnición se restauran.",
