    "pan.keep.tip": "El torreón es la única estructura de su región. Su guarnición es un múltiplo de una Gran Fortaleza, así que no puede tomarse de una vez — se toma con incursiones repetidas mientras dure la ventana de heridas.",
    "pan.keep": "<b>Torreón de {kraj}</b> — quien lo tenga controla la región",
