    "pan.keep.tvuj": "lo controlas",
    "pan.keep.drzi": "en poder de {rod}",
    "pan.keep.obrana": "<b>Un ejército de {muzu} hombres</b> bajo un solo comandante — tu héroe más fuerte lleva {strop}, unas <b>{nasobek} veces menos de lo necesario</b>. Pero el progreso SE SUMA dentro de la ventana de heridas: se desmonta con incursiones y entre varios.",
    "pan.zran.tip": "Desde el primer ataque la guarnición deja de curarse y el progreso se suma entre todos los atacantes. Cuando la ventana expira, la casilla vuelve a su fuerza total.",
    "pan.zran": "<b>Ventana de heridas {doba}</b> · guarnición desmontada al <b>{pct} %</b> · no se cura",
    "pan.trun.primeri": "La Ciudad del Trono está bajo tregua — se abre en {doba}.",
    "pan.keep.obrana.tip": "El torreón lo defiende UN ejército, no oleadas — pero tan grande que nadie puede llevar suficiente de una vez. La ventana de heridas (60 minutos) mantiene abierta la guarnición y el progreso SE SUMA entre atacantes, así que el torreón se desmonta poco a poco y entre varios.",
    "pan.kapital": "El corazón de tu reino. Las unidades en reserva defienden la ciudad, y cada gestión se abre en la barra de la derecha:",
