let jazyk = JAZYK_VYCHOZI;

// Jazyk patří na ÚČET (hráč se přihlásí z jiného zařízení), localStorage je
// jen záloha pro nepřihlášeného návštěvníka a první tip bere z prohlížeče.
function jazykZProhlizece() {
  const l = (typeof navigator !== "undefined" && navigator.language || "").slice(0, 2).toLowerCase();
  return JAZYKY_SEZNAM.some(j => j.kod === l) ? l : JAZYK_VYCHOZI;
}
function nactiJazyk() {
  let ulozeny = null;
  try { ulozeny = localStorage.getItem("vp-jazyk"); } catch (e) {}
  jazyk = JAZYKY_SEZNAM.some(j => j.kod === ulozeny) ? ulozeny : jazykZProhlizece();
  return jazyk;
}
// Na přepnutí jazyka se musí strhnout i OBSAHOVÉ TABULKY v game.js (budovy,
// události, mistrovské bonusy…). Slovník o nich nesmí vědět — proto registr
// funkcí: game.js si sem při načtení pověsí svou `prepisTabulky`.
const _poslouchaci = [];
function naPrepnuti(fn) { if (typeof fn === "function") _poslouchaci.push(fn); }
function nastavJazyk(kod, ulozit = true) {
  if (!JAZYKY_SEZNAM.some(j => j.kod === kod)) return false;
  jazyk = kod;
  if (ulozit) { try { localStorage.setItem("vp-jazyk", kod); } catch (e) {} }
  for (const fn of _poslouchaci) { try { fn(kod); } catch (e) {} }
  return true;
}
function aktualniJazyk() { return jazyk; }

// PŘEKLADOVÁ FUNKCE SE JMENUJE `tx`, NE `t` — v game.js i main.js je `t`
// obsazené jako dlaždice (`for (const t of G.tiles.values())`) na stovkách
// míst a globální `t` by se v každé takové smyčce zastínilo.
//
// {klic} v šabloně se nahradí hodnotou z `param`. Chybějící klíč spadne na
// češtinu a když ani ta není, ukáže se ⟨klic⟩ — tiché prázdno by se hledalo
// měsíce.
function tx(klic, param) {
  const s = (SLOVNIK[jazyk] && SLOVNIK[jazyk][klic])
    || (SLOVNIK[JAZYK_VYCHOZI] && SLOVNIK[JAZYK_VYCHOZI][klic]);
  if (s === undefined) return "⟨" + klic + "⟩";
  if (!param) return s;
  return s.replace(/\{(\w+)\}/g, (cely, k) => {
    const v = param[k];
    if (v === undefined) return cely;
    // Vnořený klíč: parametr smí být sám {klic,param}. Server tak nemusí
    // skládat vedlejší frázi česky — vloží jen další klíč a věta se přeloží
    // celá až u klienta.
    if (v && typeof v === "object" && v.klic) return tx(v.klic, v.param);
    return v;
  });
}
// Vždycky ČESKY, ať je nastavený jakýkoli jazyk. Server tím skládá záložní
// větu do záznamu kroniky — starší klient (nebo klient bez slovníku) tak
// uvidí aspoň něco místo prázdna.
function txCs(klic, param) {
  const puvodni = jazyk;
  jazyk = JAZYK_VYCHOZI;
  const s = tx(klic, param);
  jazyk = puvodni;
  return s;
}

// existuje klíč? (pro testy a nástroj na pokrytí — ptá se na KONKRÉTNÍ jazyk)
function maKlic(klic, kod) { return !!(SLOVNIK[kod || jazyk] || {})[klic]; }
// Zná ho slovník VŮBEC? Pro rozhodnutí „přeložit, nebo nechat českou
// předlohu z tabulky se musí ptát i na češtinu, jinak by chybějící
// španělský řádek shodil i český překlad, který existuje.
function znaKlic(klic) { return maKlic(klic) || maKlic(klic, JAZYK_VYCHOZI); }

if (typeof module !== "undefined" && module.exports) {
  module.exports = { SLOVNIK, JAZYKY_SEZNAM, JAZYK_VYCHOZI, tx, txCs, maKlic, znaKlic,
    nastavJazyk, naPrepnuti, aktualniJazyk, cisloJazyk, nactiJazyk, jazykZProhlizece };
}
